insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f046','geological-assistant','geological-assistant-m1','Remote sensing in structural mapping','A lineament is a mappable straight or gently curved linear feature of the surface, believed to reflect a subsurface structure such as a fault, fracture or shear zone.','The term was introduced by Hobbs (1904) and the widely used definition is by O''Leary and others (1976).',null,true,3,1,322) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f047','geological-assistant','geological-assistant-m1','Remote sensing in structural mapping','Lineaments appear on images as straight stream segments, aligned vegetation or tonal lines and linear scarps; low sun-angle images and radar images enhance them.','Long shadows exaggerate small relief. Lineament trends are then summarised in a rose diagram.',null,true,2,2,323) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f048','geological-assistant','geological-assistant-m1','Remote sensing in structural mapping','On stereo photos and images, dip direction is read from dip slopes and the ''rule of V''s'', and folds are recognised from curved, closing outcrop patterns of marker beds.','An outcrop makes a V across a valley that points in the dip direction (for dips steeper than the stream slope). Remember vertical exaggeration makes dips look steeper.',null,true,2,2,324) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f049','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','In hard-rock terrain, lineaments and especially lineament intersections mark fracture zones that are favourable sites for high-yielding bore wells.','Crystalline rock stores water only in cracks and weathered zones. Most of Kerala''s midland and highland is such hard rock.',null,true,3,1,325) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f050','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','Valley fills, buried pediments, deeply weathered pediplains, alluvial plains and palaeochannels are good groundwater prospect zones; inselbergs, structural hills and rocky pediments are poor (run-off zones).','Thick loose or weathered material stores water. Bare rock hills shed the rain as run-off.',null,true,3,1,326) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f051','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','Groundwater potential zones are mapped in GIS by weighted overlay of thematic layers such as geology, geomorphology, lineament density, drainage density, slope, soil, land use and rainfall.','High lineament density and gentle slope favour recharge; high drainage density and steep slope favour run-off. Weights are often set by AHP (pairwise comparison).',null,true,3,1,327) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f052','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','Under the Rajiv Gandhi National Drinking Water Mission, NRSA (now NRSC) prepared groundwater prospects (hydrogeomorphological) maps at 1:50,000 scale from IRS satellite data.','These maps guide where to drill wells and where to build recharge structures. They are served through the Bhuvan ''Bhujal'' portal.',null,true,2,2,328) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f053','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','The GRACE twin satellites (launched 2002; follow-on GRACE-FO 2018) measure changes in Earth''s gravity, used to estimate changes in groundwater storage over large regions.','Losing a big mass of water slightly lowers local gravity. GRACE data showed heavy groundwater depletion in north-west India.',null,true,2,2,329) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f054','geological-assistant','geological-assistant-m1','Remote sensing in mineral exploration','In mineral exploration, images are used to map hydrothermal alteration: iron oxides (gossans) show in visible bands, and clay or hydroxyl minerals show an absorption feature near 2.2 µm in shortwave infrared.','Altered rock around ore bodies is far larger than the ore itself, so it is an easy target. Landsat TM ratio 5/7 highlights clays and 3/1 highlights iron oxides.',null,true,3,1,330) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f055','geological-assistant','geological-assistant-m1','Remote sensing in mineral exploration','ASTER (on NASA''s Terra satellite, 1999) has 14 bands including six shortwave-infrared and five thermal bands, making it widely used for mapping alteration minerals and rock types.','Several narrow shortwave-infrared bands separate clay, carbonate and mica groups better than the single broad Landsat band.',null,true,2,2,331) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f056','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Landsat-1, launched by the USA in 1972 as ERTS-1, was the first earth-resources satellite; Landsat Thematic Mapper data have 30 m resolution and a 16-day repeat cycle.','Landsat gives the longest continuous record of the Earth''s land surface. Its scene is about 185 km wide.',null,true,3,1,332) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f057','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','As of 2026, Landsat 8 (launched 2013) and Landsat 9 (launched 2021) are operating, together imaging the Earth every 8 days; Landsat 7 (1999) was decommissioned on 4 June 2025.','Two satellites, each on a 16-day cycle and offset from one another, halve the wait to 8 days. NASA plans the next one, Landsat 10, for about 2031.',null,true,2,2,333) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f058','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','SPOT-1, launched by France (CNES) in 1986, introduced pushbroom scanning and off-nadir pointing for stereo imaging, with 10 m panchromatic and 20 m multispectral data.','Its mirror could look sideways, so the same area could be seen from two orbits to get a 3D view.',null,true,2,2,334) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f059','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','In Europe''s Copernicus programme, Sentinel-1 carries a C-band SAR and Sentinel-2 carries a 13-band multispectral imager with 10 m best resolution and 5-day revisit; data are free.','Sentinel-1A was launched in 2014 and Sentinel-2A in 2015. The newest radar unit, Sentinel-1D, was launched on 4 November 2025 by Ariane 6.',null,true,2,2,335) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f060','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','The Shuttle Radar Topography Mission (SRTM), flown on Space Shuttle Endeavour in February 2000, used radar interferometry to produce a near-global digital elevation model.','It is the most widely used free elevation data (30 m and 90 m grids) for drainage and slope analysis.',null,true,3,1,336) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f061','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Aryabhata (1975) was India''s first satellite and Bhaskara-I (1979) was India''s first experimental remote sensing satellite; both were launched by Soviet rockets.','Bhaskara carried TV cameras and a microwave radiometer. It prepared the way for the operational IRS series.',null,true,2,2,337) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f062','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','IRS-1A, India''s first operational remote sensing satellite, was launched on 17 March 1988 by a Soviet Vostok rocket and carried LISS-I (72.5 m) and LISS-II (36.25 m) cameras.','LISS means Linear Imaging Self-Scanning sensor, a pushbroom scanner. IRS-1C (1995) later added a 5.8 m panchromatic camera.',null,true,3,1,338) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f063','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Resourcesat satellites carry three cameras: LISS-IV (5.8 m), LISS-III (23.5 m) and AWiFS (56 m); Resourcesat-1 was launched in 2003, Resourcesat-2 in 2011 and Resourcesat-2A in 2016.','Finer camera, narrower strip: AWiFS covers a very wide swath for crop monitoring; LISS-IV gives village-level detail.',null,true,3,1,339) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f064','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Cartosat-1 (2005) carried two 2.5 m panchromatic cameras for along-track stereo mapping; Cartosat-3 (November 2019) gives about 0.25 m panchromatic resolution.','''Carto'' stands for cartography (map making). Cartosat-1 stereo pairs were used to build the CartoDEM elevation model of India.',null,true,3,1,340) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f065','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','RISAT-2 (2009, X-band) was India''s first radar imaging satellite; RISAT-1 (2012) was the first indigenous one, with a C-band SAR; EOS-04 (RISAT-1A) followed in February 2022.','RISAT means Radar Imaging Satellite. Radar sees through monsoon cloud, so it is used for flood and kharif crop mapping.',null,true,2,2,341) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f066','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Oceansat-1 (IRS-P4, 1999) was India''s first ocean-observation satellite; Oceansat-2 followed in 2009 and Oceansat-3 (EOS-06) in November 2022; the main sensor is the Ocean Colour Monitor.','Ocean colour shows chlorophyll, which marks likely fishing zones. Later Oceansats also carry a scatterometer for sea-surface winds.',null,true,2,2,342) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f067','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Chandrayaan-1, India''s first Moon mission, was launched on 22 October 2008 by PSLV; its data confirmed water (hydroxyl) molecules on the lunar surface.','The finding came from NASA''s Moon Mineralogy Mapper carried on board. The orbiter worked until August 2009.',null,true,3,1,343) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f068','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Chandrayaan-3 soft-landed near the lunar south pole on 23 August 2023, making India the fourth country to soft-land on the Moon and the first near the south pole.','It was launched on 14 July 2023 by LVM3. Chandrayaan-2 (2019) lost its lander, but its orbiter is still working.',null,true,3,1,344) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f069','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','The Mars Orbiter Mission (Mangalyaan) was launched on 5 November 2013 by PSLV-C25 and entered Mars orbit on 24 September 2014, on India''s first attempt.','India was the first Asian country to reach Mars orbit. Contact with the orbiter was lost in 2022.',null,true,3,1,345) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f070','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Aditya-L1, India''s first solar observatory in space, was launched on 2 September 2023 and placed in a halo orbit around the Sun-Earth L1 point on 6 January 2024.','L1 is about 1.5 million km from Earth towards the Sun. From there the Sun is seen without any eclipse.',null,true,3,1,346) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f071','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','NISAR, the joint NASA-ISRO radar satellite, was launched on 30 July 2025 by GSLV-F16; it carries L-band (NASA) and S-band (ISRO) SAR and images land and ice every 12 days.','It is the first SAR satellite to carry two radar bands. It orbits at about 747 km and was declared operational in November 2025.',null,true,3,1,347) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f072','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','The National Remote Sensing Centre (NRSC) of ISRO, at Hyderabad, receives, processes and distributes satellite data; the Indian Institute of Remote Sensing (IIRS) is at Dehradun.','NRSC''s ground station is at Shadnagar near Hyderabad. IIRS is the training institute.',null,true,3,1,348) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f073','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Bhuvan is ISRO''s web geoportal, launched in 2009 and run by NRSC, giving online maps, satellite imagery and thematic layers of India.','Bhuvan means ''Earth'' in Sanskrit. Satellite data sets themselves are downloaded from NRSC''s Bhoonidhi portal.',null,true,2,2,349) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f074','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','GPS (USA) has a nominal 24 satellites in six orbital planes at about 20,200 km altitude; at least four satellites must be in view for a 3D position fix.','Three distances fix the position and the fourth corrects the receiver''s clock error. Positions are given on the WGS 84 datum.',null,true,3,1,350) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f075','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','NavIC (IRNSS), India''s regional navigation system, is designed with seven satellites (three geostationary, four inclined geosynchronous) covering India and about 1500 km around it.','Run by ISRO. In 2026 it fell to three working satellites (IRNSS-1F''s last atomic clock failed in March 2026), fewer than the four needed for a fix; NVS-03 was due for launch in October 2026 - recheck the count before the exam.',null,false,2,2,351) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f076','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','A GIS is a computer-based system to capture, store, manage, analyse and display geographically referenced data; its components are hardware, software, data, people and methods.','What makes it more than a drawing tool is analysis: it can combine map layers to answer ''where'' questions.',null,true,3,1,352) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f077','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','GIS data have two linked parts: spatial data (location and shape of features) and attribute data (descriptive information stored in tables).','Example: a well is a point (spatial); its depth, yield and water quality are attributes.',null,true,2,2,353) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f078','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','The vector data model represents features as points, lines and polygons defined by x,y coordinates, for example wells, streams and watershed boundaries.','It suits features with sharp boundaries. It gives neat maps and small file sizes.',null,true,3,1,354) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f079','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','The raster data model represents space as a grid of cells (pixels), each holding one value; satellite images and digital elevation models are raster data.','It suits things that change gradually, like elevation or rainfall. The cell size sets the detail.',null,true,3,1,355) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f080','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','Raster data have a simple structure and make overlay easy but need more storage; vector data are compact, precise and store topology but overlay is more complex.','Hook: ''raster is faster, vector is corrector''. The choice depends on the type of data and analysis.',null,true,3,1,356) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f081','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','Topology in GIS is the set of spatial relationships between features that do not change with stretching: adjacency, connectivity and containment.','It tells which polygons share a boundary and which lines join at a node. It allows network tracing and error checking.','GATE 2026 Geomatics Engineering (GE)',true,3,1,357) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f082','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','Overlay analysis combines two or more map layers of the same area to create a new layer; common vector overlays are union, intersect and identity.','Intersect keeps only the common area; union keeps everything. Overlay is the core tool in groundwater potential and site-selection studies.',null,true,3,1,358) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f083','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','A digital elevation model (DEM) is a raster grid of elevation values; a TIN (triangulated irregular network) is a vector surface built from triangles joining irregularly spaced points.','From a DEM a GIS derives slope, aspect, hill-shade, drainage network and watershed boundaries.',null,true,3,1,359) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f084','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','Common free DEM sources are SRTM (radar interferometry), ASTER GDEM (optical stereo) and CartoDEM (ISRO, from Cartosat-1 stereo images).','Stereo pairs or radar phase give height. CartoDEM for India is available through Bhuvan.',null,true,2,2,360) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f085','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','The UTM projection divides the Earth into 60 north-south zones, each 6° of longitude wide; Kerala lies in UTM zone 43 North (72°E to 78°E).','Zone number = whole part of (longitude + 180) / 6, plus 1. For 76°E this gives 43.',null,true,2,2,361) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f086','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Reflectance of dry bare soil rises gently and steadily from visible to near- and shortwave-infrared; moisture, organic matter, iron oxide and surface roughness all lower it.','Wet soil looks darker than dry soil. The soil curve has no sharp peaks like the vegetation curve, only water absorption dips near 1.4 and 1.9 µm.',null,true,3,1,362) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f087','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','The ground resolution cell of a scanner = IFOV (in radians) x flying height; an IFOV of 0.1 milliradian from 700 km gives a 70 m cell.','IFOV (instantaneous field of view) is the tiny cone angle seen by one detector. A higher orbit or a wider angle gives a coarser pixel.',null,true,2,2,363) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f088','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Mie scattering is caused by particles about as large as the wavelength (dust, smoke); non-selective scattering by much larger water droplets affects all visible wavelengths equally, so clouds and fog look white.','Three types by particle size: gas molecules (Rayleigh), dust and smoke (Mie), water droplets (non-selective). Equal scattering of all colours gives white.',null,true,2,2,364) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f089','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Stefan-Boltzmann law: the total energy emitted by a blackbody per unit area is proportional to the fourth power of its absolute temperature (M = σT^4).','Doubling the temperature gives 16 times the energy. Real surfaces emit less than a blackbody (a perfect emitter); that fraction is called emissivity.','GATE 2026 Geomatics Engineering (GE)',true,2,2,365) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f090','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Photogrammetry is the science of obtaining reliable measurements of objects and terrain (distances, heights, maps) from photographs, mainly overlapping vertical aerial photographs.','Photo = light, gram = drawing, metry = measurement. Standard mapping photos are 23 cm x 23 cm, usually taken with a 152 mm lens.',null,true,3,1,366) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f091','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','An orthophoto is an aerial photograph from which camera tilt and relief displacement have been removed, so it has a uniform scale and can be measured like a map.','It keeps the picture detail of a photo but has the geometry of a map. A digital elevation model is needed to make it.',null,true,2,2,367) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f092','geological-assistant','geological-assistant-m1','Concepts and principles of aerial photography and photogrammetry','Air base (ground distance between successive exposure stations) = ground length covered by one photo x (1 - forward overlap); with 60% overlap it is 40% of the photo coverage.','Example: a 23 cm photo at 1:20,000 covers 4.6 km, so the air base is 0.4 x 4.6 = 1.84 km.',null,true,2,2,368) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f093','geological-assistant','geological-assistant-m1','Satellite remote sensing - data products and their interpretation','Satellite scenes are indexed by path and row numbers (e.g. Landsat''s Worldwide Reference System) and supplied at processing levels from raw data to radiometrically corrected, georeferenced and orthorectified products.','Path is the orbit track and row is the position along it. Users normally order corrected products as digital files such as GeoTIFF.',null,true,2,2,369) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f094','geological-assistant','geological-assistant-m1','Digital image processing','Image fusion (pan-sharpening) merges a high-resolution panchromatic image with lower-resolution multispectral bands to give a sharp colour image; IHS and Brovey transforms are common methods.','A panchromatic band is one broad band, so it can have smaller pixels. Fusion borrows its sharpness, e.g. Landsat 8''s 15 m band sharpens the 30 m colour bands.',null,true,2,2,370) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f095','geological-assistant','geological-assistant-m1','Digital image processing','Principal component analysis (PCA) converts correlated spectral bands into uncorrelated components; the first component (PC1) holds the largest share of the total variance.','Neighbouring bands often repeat the same information. PCA packs most of it into the first two or three components, so fewer images need study.','GATE 2026 Geomatics Engineering (GE)',true,3,1,371) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f096','geological-assistant','geological-assistant-m1','Remote sensing in landform and land use mapping','Land cover is what physically covers the ground (forest, water, bare rock); land use is how people use it (farming, housing). Images record land cover directly, and land use is inferred.','A grassy area is one land cover but may be a pasture, a park or an airfield. So field checks are needed for land use maps.',null,true,2,2,372) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f097','geological-assistant','geological-assistant-m1','Remote sensing in landform and land use mapping','Change detection compares co-registered images of the same area from two or more dates to map changes such as urban growth, forest loss, shoreline shift and conversion of wetlands or paddy fields.','The images must overlay exactly and be of the same season, or false changes appear. The regular revisit of satellites makes this possible.',null,true,2,2,373) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f098','geological-assistant','geological-assistant-m1','Remote sensing in landform and land use mapping','Landforms are identified on images from their shape and relief (seen in stereo or on a DEM), drainage pattern, tone and texture, and the vegetation and land use on them.','Example: a flat, dark-toned, cultivated strip along a stream is a valley fill; a bare, light-toned isolated hill is an inselberg.',null,true,2,2,374) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f099','geological-assistant','geological-assistant-m1','Remote sensing in landform and land use mapping','The Kerala State Remote Sensing and Environment Centre (KSREC), Thiruvananthapuram, is the State Government''s nodal agency for remote sensing and GIS applications.','It prepares land use, watershed and other resource maps for State departments from satellite data.',null,true,2,2,375) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f100','geological-assistant','geological-assistant-m1','Remote sensing in structural mapping','Faults are recognised on images by straight scarps, abrupt offset or truncation of beds, ridges and streams, and sharp linear breaks in tone or vegetation.','A fault cuts and shifts whatever it crosses. So look for features that end suddenly or are displaced along a straight line.',null,true,2,2,376) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f101','geological-assistant','geological-assistant-m1','Remote sensing in structural mapping','Dolerite dykes usually appear on images as narrow, straight, dark-toned linear features cutting across the country rock; they can act as underground barriers to groundwater flow.','Dolerite is a dark, basic rock, so its tone is dark. Wells on the upstream side of a dyke often hold more water.',null,true,2,2,377) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f102','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','Remote sensing cannot detect groundwater directly; it maps surface indicators (landforms, lineaments, vegetation, soil moisture, springs), which must be confirmed by geophysical survey and drilling.','Most sensors see only the ground surface. So images narrow down the target area, and resistivity survey then fixes the well site.',null,true,3,1,378) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f103','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','Thermal infrared images can locate springs, seeps and submarine groundwater discharge, because groundwater has a nearly constant temperature that contrasts with surface water.','Groundwater is cooler than sea or lake water on a summer day and warmer on a cold night. The plume shows as a different tone.',null,true,2,2,379) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f104','geological-assistant','geological-assistant-m1','Remote sensing in hydrogeological studies','On dry-season images, lines or patches of healthy vegetation (bright red on a standard FCC) in otherwise dry ground point to shallow groundwater or moist fracture zones.','Plants stay green in summer only where roots reach water. A straight line of such vegetation often follows a water-bearing fracture.',null,true,2,2,380) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f105','geological-assistant','geological-assistant-m1','Remote sensing in mineral exploration','Geobotanical remote sensing finds mineralised ground through stressed vegetation: metal-rich soil shifts the ''red edge'' of the leaf reflectance curve towards shorter wavelengths (blue shift).','The red edge is the steep rise in reflectance near 0.7 µm. This helps in forested areas where rocks and soil are hidden.',null,true,1,3,381) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f106','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','HysIS, India''s hyperspectral imaging satellite, was launched on 29 November 2018 by PSLV-C43; it images in visible, near-infrared and shortwave-infrared bands at 30 m resolution.','''Hys'' is short for hyperspectral. Its many narrow bands help in mineral, soil and crop studies.',null,true,2,2,382) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f107','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Landsat sensors evolved from MSS (4 bands, about 80 m) to TM (7 bands, 30 m; Landsat 4 and 5), ETM+ (Landsat 7; adds a 15 m panchromatic band) and OLI plus TIRS (Landsat 8 and 9).','MSS = Multispectral Scanner, TM = Thematic Mapper, OLI = Operational Land Imager, TIRS = Thermal Infrared Sensor. Landsat 6 (1993) failed to reach orbit.',null,true,3,1,383) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f108','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Since 2020 ISRO names its earth observation satellites ''EOS'': EOS-01 (2020), EOS-04 or RISAT-1A (2022), EOS-06 or Oceansat-3 (2022) and EOS-08 (16 August 2024, by SSLV-D3).','SSLV is ISRO''s Small Satellite Launch Vehicle. EOS-09 (RISAT-1B) was lost when PSLV-C61 failed on 18 May 2025.',null,true,2,2,384) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f109','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','INSAT-3D (2013), INSAT-3DR (2016) and INSAT-3DS (17 February 2024, by GSLV-F14) are India''s geostationary weather satellites, each carrying an imager and an atmospheric sounder.','From geostationary orbit they watch India continuously, which suits cyclone and monsoon tracking. The sounder gives temperature and humidity profiles.',null,true,2,2,385) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f110','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','India''s space programme began at Thumba, Thiruvananthapuram, where the first sounding rocket was launched on 21 November 1963; the Vikram Sarabhai Space Centre (VSSC) there is ISRO''s lead centre for launch vehicles.','Thumba lies close to the magnetic equator. Satellites are launched from the Satish Dhawan Space Centre at Sriharikota, Andhra Pradesh.',null,true,3,1,386) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f111','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','PSLV is ISRO''s workhorse rocket for placing remote sensing satellites in sun-synchronous polar orbit; GSLV and LVM3 carry heavier satellites, mainly to geosynchronous transfer orbit.','P stands for Polar and G for Geosynchronous. Chandrayaan-1, Mangalyaan and Aditya-L1 also flew on PSLV; Chandrayaan-3 flew on LVM3.',null,true,2,2,387) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f112','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Global navigation satellite systems are GPS (USA), GLONASS (Russia), Galileo (European Union) and BeiDou (China); NavIC (India) and QZSS (Japan) are regional systems.','GNSS is the common name for all of them. A modern receiver uses several systems together to get more satellites in view.',null,true,3,1,388) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f113','geological-assistant','geological-assistant-m1','Global and Indian Space Missions','Differential GPS (DGPS) uses a base receiver at a precisely known point to compute corrections for a roving receiver, improving accuracy from several metres to sub-metre level.','Both receivers see nearly the same satellite and atmosphere errors, so these cancel. India''s GAGAN system (ISRO and Airports Authority of India) sends similar corrections by satellite.',null,true,2,2,389) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f114','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','A datum is a reference ellipsoid fixed to the Earth for defining coordinates; GPS uses the global WGS 84 datum, while older Survey of India maps used the Everest ellipsoid.','The same point gets slightly different latitude and longitude on different datums, so all layers must share one. New Survey of India Open Series Maps use WGS 84 with UTM.',null,true,3,1,390) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f115','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','A map projection transfers the curved Earth to a flat sheet and always distorts something: conformal projections keep shape (angles), equal-area projections keep area; no projection keeps both.','UTM is a conformal (transverse Mercator) projection. Old Survey of India toposheets used the polyconic projection.',null,true,2,2,391) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f116','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','Buffering creates a zone (a polygon) of chosen distance around a point, line or polygon feature, for example a 500 m protection zone around a drinking-water well.','The output is always an area, whatever the input shape. It answers ''what lies within this distance of that feature?''','GATE 2026 Geomatics Engineering (GE)',true,2,2,392) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f117','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','Spatial interpolation estimates values at unsampled places from point data; common methods are inverse distance weighting (IDW) and kriging, used to make water-table and rainfall maps from well and rain-gauge data.','IDW simply gives nearer points more weight. Kriging is a geostatistical method based on the semivariogram and also gives the likely error.',null,true,2,2,393) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f118','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','A digital surface model (DSM) includes the tops of trees and buildings; a digital terrain model (DTM) shows the bare ground. LiDAR, which times laser pulses, gives very detailed elevation models.','Some laser pulses pass through gaps in the tree canopy and reach the ground, so LiDAR can map the bare earth under forest.',null,true,2,2,394) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u1c-f119','geological-assistant','geological-assistant-m1','Geographic Information System (GIS) - principles and applications','A GIS stores information as separate thematic layers (e.g. geology, drainage, wells, land use) registered to one common coordinate system so that they can be overlaid and analysed together.','Think of transparent map sheets stacked exactly one over another. Each layer holds one theme only.',null,true,3,1,395) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f001','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','Stress is force per unit area (SI unit: pascal). Strain is the change in shape or volume that stress produces, and it has no units.','Stress is the cause, strain is the effect. Strain is a ratio (change in length / original length), so the units cancel.',null,true,3,1,396) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f002','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','The strain ellipsoid is the shape a sphere takes after homogeneous strain. Its axes are X ≥ Y ≥ Z: longest, intermediate and shortest.','Think of squeezing a ball of clay: it becomes an egg or a disc. X is the stretch direction, Z is the squeeze direction.',null,true,3,1,397) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f003','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','Pure shear is coaxial (non-rotational) strain. Simple shear is non-coaxial (rotational) strain.','Pure shear = squeezing a block flat; the strain axes do not turn. Simple shear = pushing the top of a pack of cards sideways; the strain axes rotate.',null,true,3,1,398) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f004','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','Elongation e = (final length − original length) / original length. Stretch S = 1 + e. Quadratic elongation λ = (1 + e)².','Example: a 10 cm fossil stretched to 15 cm has e = 0.5, S = 1.5 and λ = 2.25. Shortening gives a negative e.',null,true,2,2,399) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f005','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','The Flinn diagram plots the axial ratio a = X/Y on the vertical axis against b = Y/Z on the horizontal axis.','It shows the shape of any strain ellipsoid as one point on a graph. An unstrained sphere plots at the origin (1, 1).',null,true,3,1,400) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f006','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','Flinn''s k = (a − 1)/(b − 1). k = 0 means oblate (pancake) strain, k = 1 plane strain, and k = infinity prolate (cigar) strain.','Below the k = 1 line is the flattening field, above it the constriction (stretching) field. Pancakes give strong foliation; cigars give strong lineation.',null,true,3,1,401) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f007','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','Strain markers are objects of known original shape, such as ooids, reduction spots, pebbles, vesicles and fossils.','If we know the shape before deformation (for example a sphere), the shape now tells us how much the rock was strained.',null,true,3,1,402) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f008','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','The Fry method finds the strain ellipse from the centre-to-centre distances between neighbouring grains or ooids.','Before strain, grain centres are evenly spaced in all directions. After strain they are closer along the squeeze direction, and a plot of the centres shows an elliptical gap.',null,true,2,2,403) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f009','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','Wellman''s method measures strain from deformed fossils that had known original angles, such as brachiopods and trilobites.','These fossils have bilateral symmetry (left and right halves match), so the hinge line and median line were at 90°. Strain changes that angle.',null,true,2,2,404) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f010','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','With rising stress a rock first deforms elastically (recoverable), then plastically after the yield point (permanent), and finally ruptures.','Like a steel wire: a small pull springs back, a bigger pull bends it for good, and a still bigger pull snaps it.',null,true,3,1,405) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f011','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','A brittle rock breaks after very little plastic strain. A ductile rock takes a large plastic strain before it breaks.','Brittle = glass (snaps). Ductile = warm wax (flows). Faults and joints are brittle structures; folds and shear zones are ductile ones.','TNPSC Geology paper (code 394, year not stated)',true,3,1,406) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f012','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Rocks become more ductile with higher confining pressure, higher temperature, the presence of fluids and a slower strain rate.','Deep rocks are hot, tightly confined and deformed slowly, so they fold and flow. Shallow, cold, quickly loaded rocks crack.',null,true,3,1,407) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f013','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Pore-fluid pressure lowers the effective normal stress (normal stress minus pore pressure), so it weakens rock and helps faults to slip.','Water pressure in the pores pushes the grains apart and partly carries the load. On a Mohr diagram the stress circle moves left toward failure.',null,true,2,2,408) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f014','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Boudinage forms when a competent layer is stretched and breaks into sausage-shaped pieces. If the layer only necks without separating, it is pinch-and-swell structure.','Competent means strong and stiff. The stiff layer cannot stretch as much as the soft rock around it, so it necks or pulls apart.','TNPSC Geology paper (code 394, year not stated)',true,2,2,409) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f015','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Mylonite is a fine-grained, foliated rock made by ductile shearing in a shear zone. Fault breccia, gouge and cataclasite are made by brittle crushing.','In mylonite the grains get smaller by recrystallising while the rock flows. In breccia and gouge the grains are simply broken.','IIT-JAM Geology 2019',true,3,1,410) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f016','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Wavy (undulose) extinction in quartz under the microscope shows that the crystal lattice has been bent by plastic strain.','A bent crystal goes dark in a sweeping wave instead of all at once when the stage is turned. It is a quick sign of a deformed rock.',null,true,1,3,411) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f017','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','At any point there are three mutually perpendicular principal stresses, σ1 ≥ σ2 ≥ σ3. The planes they act on carry no shear stress.','σ1 is the greatest squeeze, σ3 the least. All fault and joint theory starts from the directions of these three.',null,true,3,1,412) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f018','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','The Mohr circle plots shear stress against normal stress. Its centre is at (σ1 + σ3)/2 and its radius is (σ1 − σ3)/2.','Each point on the circle is one plane in the rock. Centre = mean stress; diameter = differential stress. A bigger circle means the rock is closer to breaking.',null,true,3,1,413) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f019','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','Maximum shear stress equals (σ1 − σ3)/2 and acts on planes at 45° to σ1.','It is the top point of the Mohr circle, so its value is the radius. Example: σ1 = 100 MPa, σ3 = 40 MPa gives 30 MPa.',null,true,3,1,414) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f020','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','Real shear fractures form at about 30° to σ1, not 45°, because of internal friction (Coulomb criterion: τ = C + σn tan φ).','C is cohesion (built-in strength) and φ the friction angle. Friction makes it easier to slip on planes closer to σ1, where the normal stress is lower.',null,true,2,2,415) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f021','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','In conjugate shear fractures, σ1 bisects the acute angle, σ3 bisects the obtuse angle, and the line of intersection is parallel to σ2.','Conjugate means a matching pair formed together, like an X. The squeeze direction (σ1) points into the narrow part of the X.','GATE Geology and Geophysics 2022',true,3,1,416) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f022','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','Anderson''s theory: the Earth''s surface carries no shear stress, so one principal stress is vertical. σ1 vertical gives normal faults, σ2 strike-slip faults, σ3 thrust faults.','Hook: 1-2-3 = Normal, Strike-slip, Thrust. In normal faults gravity is the biggest stress; in thrusts the horizontal squeeze is biggest and the vertical load is least.','GATE Geology and Geophysics 2021',true,3,1,417) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f023','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','Anderson''s theory predicts dips of about 60° for normal faults, about 30° for thrust faults, and vertical for strike-slip faults.','Faults form at about 30° to σ1. With σ1 vertical that is a 60° dip; with σ1 horizontal it is a 30° dip.',null,true,3,1,418) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f024','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','Buckling is folding by compression parallel to the layers. Bending is folding by forces acting across the layers, as over a rising intrusion or fault block.','Push the two ends of a ruler together and it buckles. Push up under the middle of a sheet and it bends.',null,true,2,2,419) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f025','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','In flexural-slip folding, layers slide past each other along bedding planes, like a bent pack of cards. It gives parallel folds.','Each bed keeps its thickness. Proof in the field: slickensides (scratch marks) on bedding planes at right angles to the fold hinge.',null,true,3,1,420) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f026','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','In passive (shear) folding the layers are only markers; slip on closely spaced planes parallel to the axial plane produces similar folds.','The layering has no strength of its own here. This happens in hot, soft rocks and gives thick hinges and thin limbs.',null,true,2,2,421) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f027','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Strike is the direction of a horizontal line on an inclined plane. Dip is the steepest angle of slope of the plane, measured at right angles to strike.','On a sloping roof, the ridge line is the strike and the path rainwater takes is the dip direction.','TNPSC Geology paper (code 394, year not stated)',true,3,1,422) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f028','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','True dip is the maximum dip. Apparent dip in any other direction is smaller: tan(apparent dip) = tan(true dip) × sin(angle between section and strike).','Along the strike the apparent dip is zero; at right angles to strike it equals the true dip. Example: true dip 45°, section 30° from strike, apparent dip about 27°.',null,true,3,1,423) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f029','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Plunge is the angle between a line and the horizontal, measured in a vertical plane. Pitch (rake) is the angle between a line and the strike, measured within the plane holding the line.','Plunge is for any line (fold axis, lineation). Pitch is used for a line lying on a plane, such as scratches on a fault surface.',null,true,3,1,424) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f030','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Structure contours (strike lines) join points of equal height on a geological surface. tan(dip) = contour interval / horizontal spacing between contours.','They work like topographic contours, but for a buried bed. Closely spaced contours mean a steep dip.','IIT-JAM Geology 2019',true,2,2,425) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f031','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Rule of V''s: outcrops of horizontal beds follow the topographic contours and V upstream; outcrops of vertical beds run straight across valleys.','A horizontal bed is at one height everywhere, just like a contour. A vertical bed is not shifted sideways by any change in ground height.',null,true,3,1,426) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f032','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Rule of V''s: a bed dipping downstream more steeply than the valley floor Vs downstream; a bed dipping upstream Vs upstream.','Short rule: the V points in the direction of dip. The one exception is a bed dipping downstream more gently than the stream bed; it Vs upstream.',null,true,3,1,427) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f033','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','On level ground a plunging anticline''s outcrop closes (noses) in the direction of plunge; a plunging syncline''s outcrop closes in the opposite direction.','Non-plunging folds give straight parallel bands. Plunge makes the bands meet in a V or U shape.','IIT-JAM Geology 2019',true,2,2,428) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f034','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The Wulff net is equal-angle; the Schmidt (Lambert) net is equal-area. Structural geologists use the Schmidt net with lower-hemisphere projection for contouring data.','Equal-area keeps the density of points true, which is needed for statistics. The Wulff net keeps angles true and is preferred in crystallography.',null,true,3,1,429) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f035','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','On a stereonet a plane plots as a great circle and a line as a point. A plane can also be shown by its pole, the point 90° from its great circle.','A horizontal plane is the outer circle; a vertical plane is a straight line through the centre; a vertical line is the centre point.',null,true,3,1,430) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f036','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','For a cylindrical fold, poles to bedding lie on a great circle (π-circle) whose pole is the fold axis. In a β-diagram, bedding great circles cross at the fold axis.','π-diagram uses poles; β-diagram uses the planes themselves. Both find the fold axis from many dip readings.',null,true,2,2,431) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f037','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The hinge is the line of maximum curvature of a folded layer. The axial plane (axial surface) joins the hinge lines of successive layers.','The axial plane splits the fold into two limbs. Its attitude and the plunge of the hinge together describe how the fold sits in space.',null,true,3,1,432) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f038','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','An anticline has the oldest rocks in its core and a syncline the youngest. Antiform and synform describe only the shape (closing up or closing down).','Shape and age can disagree in overturned regions. An arch with the youngest rocks in the core is an antiformal syncline.','IIT-JAM Geology 2019',true,3,1,433) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f039','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Fleuty''s interlimb-angle classes: gentle 180–120°, open 120–70°, close 70–30°, tight 30–0°, isoclinal 0° (parallel limbs).','The interlimb angle is the angle between the two limbs. Smaller angle = tighter fold = more shortening.',null,true,3,1,434) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f040','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','An upright fold has a vertical axial plane; a recumbent fold has a horizontal axial plane; a reclined fold has a hinge plunging down the dip of its inclined axial plane.','Fleuty named folds by the dip of the axial plane and the plunge of the hinge. In a reclined fold the hinge has a pitch of about 90° on the axial plane.','IIT-JAM Geology 2019',true,3,1,435) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f041','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','In an overturned fold both limbs dip the same way, and one limb is upside down (rotated past vertical).','On the upside-down limb, older beds lie on top of younger beds. Way-up clues such as graded bedding and cross-bedding reveal this.','TNPSC Geology paper (code 394, year not stated)',true,2,2,436) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f042','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Ramsay''s fold classification uses dip isogons: lines joining points of equal dip on the upper and lower surfaces of a folded layer.','The isogon pattern shows how layer thickness changes from hinge to limb. Three patterns: convergent (Class 1), parallel (Class 2), divergent (Class 3).',null,true,3,1,437) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f043','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Ramsay Class 1 folds have convergent isogons. Class 1B is the parallel (concentric) fold, with constant thickness measured at right angles to the layer.','In Class 1B the isogons are perpendicular to the layer. Parallel folds form by buckling of strong (competent) beds.',null,true,3,1,438) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f044','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Ramsay Class 2 folds have parallel isogons and are similar folds. Class 3 folds have divergent isogons.','In a similar fold every layer has the same shape, so thickness measured parallel to the axial plane is constant. Hinges are thick, limbs thin.',null,true,3,1,439) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f045','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','A chevron fold has straight limbs and a sharp hinge. A box fold has two hinges and three limbs. A fan fold has both limbs overturned.','Chevron looks like a zigzag (V). Box looks like a flat-topped rectangle. Fan looks like an open hand-fan, pinched at the base.','TNPSC Geology paper (code 394, year not stated)',true,2,2,440) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f046','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Foliation is any planar fabric that runs through a rock; lineation is any linear fabric. Slaty cleavage is a foliation made by parallel, very fine platy minerals.','Foliation = sheets (like pages). Lineation = lines (like pencils in a box). Slate splits into thin plates along its cleavage.',null,true,3,1,441) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f047','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Axial-plane cleavage lies roughly parallel to fold axial planes. It forms at right angles to the direction of greatest shortening (parallel to the XY plane of the strain ellipsoid).','Platy minerals turn or grow flat-on to the squeeze, like cards flattened by a press. So cleavage tells you the squeeze direction.',null,true,3,1,442) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f048','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Crenulation cleavage forms by microfolding (crenulation) of an earlier foliation, so it records a later deformation.','Tiny wrinkles form in an older cleavage, and their limbs line up as a new cleavage. Seeing it means the rock was deformed at least twice.',null,true,2,2,443) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f049','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Where bedding and axial-plane cleavage dip the same way: cleavage steeper than bedding means a normal limb; bedding steeper than cleavage means an overturned limb.','This lets you tell which way up the beds are from one outcrop, even when the whole fold is not visible.',null,true,3,1,444) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f050','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The lineation made by the intersection of bedding and axial-plane cleavage is parallel to the fold axis.','Both planes contain the fold axis direction, so the line where they meet points along it. It is a quick way to find the plunge of a large fold.',null,true,2,2,445) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f051','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Common lineations are mineral (stretching) lineation, intersection lineation, crenulation lineation, slickenlines, boudin axes, mullions and quartz rods.','Mullions are pillar-like ribs on the surface of a strong bed. Rods are pencil-like bodies of quartz. Both usually lie parallel to fold axes.',null,true,2,2,446) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f052','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','A joint is a fracture with no visible movement parallel to its surface. Parallel joints make a joint set; two or more sets make a joint system.','If the two sides have slid past each other, it is a fault, not a joint. Joints control groundwater flow in hard rocks.',null,true,3,1,447) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f053','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','In folded rocks, longitudinal joints run parallel to the fold axis, cross (transverse) joints run at right angles to it, and diagonal joints are oblique.','Relative to bedding the same idea gives strike joints, dip joints and oblique joints. Diagonal joints often come as conjugate shear pairs.',null,true,2,2,448) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f054','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Columnar joints form by shrinkage during cooling of lava flows, sills and dykes. The columns grow at right angles to the cooling surface.','Cooling rock shrinks and cracks into polygons, like drying mud. Indian examples: Deccan Trap flows and St Mary''s Islands off Karnataka.',null,true,3,1,449) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f055','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Sheet (exfoliation) joints lie parallel to the ground surface and form by unloading. Mural joints are three sets at right angles, cutting granite into cubes.','When erosion removes the rock above, a granite body expands and peels in sheets. Mural joints make granite easy to quarry as blocks.',null,true,2,2,450) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f056','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Hanging wall = block above an inclined fault; down in a normal fault, up in a reverse fault. A thrust is a low-angle reverse fault (under 45° in Billings; some books say under 30°).','Miners named them: the hanging wall hangs over your head, the footwall is under your feet. Normal = pulling apart; reverse = pushing together.',null,false,3,1,451) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f057','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Throw is the vertical component and heave the horizontal component of dip-slip displacement, so tan(fault dip) = throw / heave. Hade is the angle between the fault plane and the vertical.','Hade = 90° − dip. Example: throw 173 m and heave 100 m give tan(dip) = 1.73, so the dip is 60° and the hade 30°.','IIT-JAM Geology 2019',true,3,1,452) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f058','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','A horst is an uplifted block and a graben a down-dropped block, each bounded by normal faults.','Both form where the crust is pulled apart. A graben makes a rift valley; the Rhine valley is the classic example.','IIT-JAM Geology 2019',true,3,1,453) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f059','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Slickensides are polished, grooved fault surfaces. The grooves (slickenlines) lie parallel to the direction of slip.','The two blocks grind against each other and scratch the surface. The scratches show the line of movement on the fault.',null,true,3,1,454) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f060','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Field signs of faults include offset, repeated or missing beds, fault breccia and gouge, drag folds, fault scarps, triangular facets and lines of springs.','Triangular facets are the cut-off ends of ridges along a fault scarp. Springs line up because crushed rock along the fault carries or dams groundwater.','IIT-JAM Geology 2019',true,3,1,455) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f061','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','A nappe is a large rock sheet moved far from its source by thrusting or recumbent folding. Moved rocks are allochthonous; rocks still in place are autochthonous.','Nappe is French for tablecloth: a sheet spread over other rocks. Allo = other place; auto = same place.',null,true,3,1,456) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f062','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','A klippe is an erosional remnant (outlier) of a thrust sheet. A window (fenster) is a hole eroded through a thrust sheet, exposing the rocks below.','Klippe = an island of the upper sheet left behind. Window = a hole in the upper sheet that lets you see the lower rocks.','TNPSC Geology paper (code 394, year not stated)',true,3,1,457) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f063','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Himalayan thrusts from north to south are the Main Central Thrust (MCT), Main Boundary Thrust (MBT) and Main Frontal Thrust (MFT). The MBT puts Lesser Himalayan rocks over the Siwaliks.','The thrusts get younger toward the south (C-B-F in order). The MCT carries the Higher Himalayan crystalline rocks over the Lesser Himalaya.',null,true,3,1,458) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f064','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','In Kerala, the NW–SE Achankovil Shear Zone separates the Madurai Block from the Trivandrum Block; the Palghat Gap lies along the E–W Palghat–Cauvery Shear Zone.','A shear zone is a belt of strongly sheared rock, the deep (ductile) form of a fault. These two are the main crustal breaks of Kerala''s basement.',null,true,2,2,459) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f065','geological-assistant','geological-assistant-m2','Superposed deformation','Ramsay Type 1 interference is the dome-and-basin (''egg-carton'') pattern. It forms when two sets of upright folds cross at a high angle.','Superposed folding means later folds (F2) bend earlier folds (F1). Where two arches cross you get a dome; where two troughs cross, a basin.',null,true,3,1,460) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f066','geological-assistant','geological-assistant-m2','Superposed deformation','Ramsay Type 2 interference is the dome–crescent–mushroom pattern. It forms when early recumbent or overturned folds are refolded by upright folds with axes at a high angle.','Because the first folds were lying down, their axial planes get folded too. Erosion then cuts crescent and mushroom shapes on the map.',null,true,2,2,461) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f067','geological-assistant','geological-assistant-m2','Superposed deformation','Ramsay Type 3 interference is the hook-shaped (convergent–divergent) pattern. It forms by coaxial refolding: fold axes nearly parallel, axial planes at a high angle.','Coaxial means both fold sets share the same axis direction. The first fold is simply bent again about that axis, giving a hook in cross-section.',null,true,2,2,462) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f068','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','A porphyroblast is a large crystal grown in the solid state during metamorphism. A phenocryst is a large crystal grown from magma.','-blast means grown in a metamorphic rock (garnet, staurolite). The tiny inclusions trapped inside a porphyroblast record the fabric at the time it grew.','IIT-JAM Geology 2019',true,2,2,463) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f069','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','Pre-tectonic porphyroblasts are wrapped by the foliation and show pressure shadows, cracks, bending or wavy extinction.','The crystal was already there when the squeeze came, so the foliation had to flow around it and the crystal itself got damaged.',null,true,3,1,464) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f070','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','Syn-tectonic porphyroblasts have curved or spiral inclusion trails (Si) that continue into the matrix foliation (Se); snowball garnet is the classic example.','Si = foliation inside the crystal, Se = foliation outside. The crystal rotated while it grew, so it trapped a spiral, like a rolling snowball.',null,true,3,1,465) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f071','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','Post-tectonic porphyroblasts grow across the foliation without bending it. Their inclusion trails are straight, or preserve earlier microfolds (helicitic texture), and match the matrix foliation.','Deformation had stopped, so the crystal quietly grew over the finished fabric. No pressure shadows, no wrapping, often random orientation.',null,true,3,1,466) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f072','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','An unconformity is a buried surface of erosion or non-deposition between older and younger rocks. The missing time is called a hiatus.','It is a gap in the rock record, like torn-out pages in a book. It shows uplift and erosion happened before deposition restarted.',null,true,3,1,467) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f073','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','In an angular unconformity, older beds were tilted or folded and eroded before younger beds were laid across them at a different dip.','The dips above and below do not match. Order of events: deposit, tilt, erode, deposit again.',null,true,3,1,468) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f074','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','In a disconformity, beds above and below are parallel but an uneven erosion surface separates them.','There was erosion but no tilting. Look for an irregular surface, old soil or a pebble bed between parallel layers.',null,true,3,1,469) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f075','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','In a paraconformity, beds are parallel and no erosion surface is visible; the gap is known only from fossils or dating.','It looks like a normal bedding plane. Only missing fossil zones show that a long time is not recorded.',null,true,2,2,470) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f076','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','In a nonconformity, sedimentary beds rest on eroded plutonic igneous or massive metamorphic rocks.','Granite forms deep down. For sediments to lie on it, kilometres of rock were eroded first, so the time gap is very large.',null,true,3,1,471) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f077','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','An inlier is an area of older rocks surrounded by younger rocks. An outlier is an area of younger rocks surrounded by older rocks.','Inliers appear where erosion cuts a hole through younger cover (valleys, eroded anticlines). Outliers are caps of younger rock left on hilltops.',null,true,2,2,472) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f078','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','The Eparchaean Unconformity separates Archaean basement from the overlying Proterozoic (Purana) rocks. It is well exposed at Tirumala, Andhra Pradesh, below Cuddapah quartzite.','Ep-Archaean means ''after the Archaean''. It is a nonconformity (sediments on granite and gneiss) and a GSI national geological monument.',null,true,3,1,473) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f079','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','In Kerala, Tertiary sediments such as the Warkalli Formation rest unconformably on Precambrian crystalline basement of khondalite, charnockite and gneiss.','This is Kerala''s own basement–cover contact. Nearly the whole Palaeozoic and Mesozoic record is missing in between.',null,true,2,2,474) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f080','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','Basement is the older crystalline (igneous and metamorphic) rock below a major unconformity; cover is the younger sedimentary sequence lying on it.','Basement is stiff and already deformed; cover is layered and weaker. So the two often deform in different ways.',null,true,2,2,475) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f081','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','In thin-skinned tectonics the cover folds and thrusts above a décollement (detachment surface) and the basement is not involved; in thick-skinned tectonics basement is faulted too.','A décollement usually follows a weak layer such as salt or shale, like a rug sliding on a floor. The Jura Mountains are the classic case.',null,true,2,2,476) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f082','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Concordant intrusions (sill, laccolith, lopolith, phacolith) lie parallel to the layering of the country rock. Discordant intrusions (dyke, batholith, stock) cut across it.','Concordant = agrees with the bedding. Discordant = disagrees. Sill is parallel to beds; dyke cuts across beds.',null,true,3,1,477) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f083','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','A laccolith has a flat floor and a domed roof. A lopolith is saucer-shaped. A phacolith is a lens along the crest or trough of a fold.','Laccolith lifts the roof (thick magma). Lopolith sags like a saucer (Bushveld, South Africa). Phacolith fills the gap that opens at a fold hinge.','IIT-JAM Geology 2019',true,3,1,478) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f084','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','A batholith is a large discordant pluton with over 100 km² of exposed area; a stock is smaller than 100 km².','Batholiths are mostly granite and form the cores of mountain belts. A round stock is called a boss.',null,true,2,2,479) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f085','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Ring dykes are vertical or dip steeply outward and form by cauldron subsidence. Cone sheets dip inward toward a magma centre.','Ring dyke: a block sinks and magma rises around it. Cone sheet: magma pushes up and fills cone-shaped cracks, like stacked funnels.',null,true,2,2,480) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f086','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Flow foliation and flow lineation in a pluton are primary structures made by moving magma; near the margins they usually lie parallel to the contacts.','Platy and rod-shaped crystals line up in flowing magma, like logs in a river. They are ''primary'' because they form before the rock is fully solid.',null,true,1,3,481) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f087','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','A diapir is a body of light, mobile rock (salt, mud or magma) that rises and pierces the denser rocks above it.','Diapir comes from Greek ''to pierce''. It rises by buoyancy, like oil rising through water, only very slowly.',null,true,3,1,482) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f088','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Salt domes rise because buried salt (density about 2.2 g/cm³) is lighter than compacted sediments and flows as a plastic solid.','Sediments get denser as they are buried and squeezed; salt does not. Below some depth the salt is the lighter layer and pushes upward.',null,true,3,1,483) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f089','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','A salt-dome cap rock has anhydrite at the base, gypsum in the middle and calcite on top; native sulphur occurs in the calcite zone.','Groundwater dissolves the salt at the top of the dome and leaves the less soluble anhydrite. Anhydrite then alters to gypsum, calcite and sulphur.',null,true,3,1,484) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f090','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Salt domes usually give a gravity low. Oil and gas are trapped in the upturned and faulted beds against their flanks and above them.','Salt is lighter than the rocks around it, so gravity is slightly weaker over it. Salt does not let fluids pass, so it seals the traps. Classic area: US Gulf Coast.',null,true,2,2,485) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f091','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','In plane strain the intermediate axis Y keeps its original length, so all the shape change is in the XZ plane. At constant volume it plots on the k = 1 line of the Flinn diagram.','Pure shear and simple shear are both plane strains. Think of a sheared card deck: it changes shape in one plane only, and its width along the cards stays the same.',null,true,2,2,486) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f092','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','The Rf/φ method finds strain from markers that were already elliptical before deformation, such as pebbles, using each marker''s final axial ratio (Rf) and long-axis direction (φ).','Pebbles do not start as perfect spheres. Plotting shape against direction for many pebbles separates the original shape from the tectonic strain.',null,true,2,2,487) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f093','geological-assistant','geological-assistant-m2','Measurement of strain in deformed rocks','In homogeneous strain, straight lines stay straight and parallel lines stay parallel, so a circle becomes an ellipse. In heterogeneous strain, straight lines become curved.','A fold is heterogeneous strain. Geologists pick small areas where strain is nearly homogeneous so that the strain-ellipse idea can be used.',null,true,2,2,488) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f094','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','An elastic solid obeys Hooke''s law: stress is proportional to strain. In a viscous (Newtonian) fluid, stress is proportional to strain rate. A plastic body flows only above a yield stress.','Models: a spring is elastic, a dashpot (piston in oil) is viscous, a block that slides only when pushed hard enough is plastic. Rocks behave as mixes of these.',null,true,3,1,489) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f095','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Young''s modulus is axial stress divided by axial strain. Poisson''s ratio is lateral strain divided by axial strain; it is about 0.25 for many rocks.','Young''s modulus tells how stiff a rock is. Poisson''s ratio tells how much it bulges sideways when squeezed lengthwise.',null,true,2,2,490) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f096','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Competent beds (quartzite, massive sandstone, limestone) are strong and buckle or fracture. Incompetent beds (shale, rock salt, phyllite) are weak and flow.','Competence means relative strength under the same conditions. In a folded pile the strong beds set the fold shape and the weak beds flow to fill the gaps.',null,true,3,1,491) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f097','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Pressure solution dissolves minerals at highly stressed grain contacts and redeposits them where stress is low. It produces stylolites and spaced solution cleavage.','It works through a water film around grains at fairly low temperature. Stylolites are the dark, toothed seams seen in limestone and marble.',null,true,2,2,492) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f098','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Calcite deforms easily by mechanical twinning and micas by kinking. Quartz deforms by dislocation creep, giving undulose extinction, deformation bands and subgrains.','Each mineral has its own easiest way to change shape. Dislocations are line defects that move through a crystal and let it flow without breaking.',null,true,2,2,493) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f099','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Creep is slow, continuous strain under a constant stress below the rock''s short-term strength. Its stages are primary (slowing), secondary (steady-state) and tertiary (speeding up to failure).','Given geological time, rocks flow under stresses far too small to break them quickly. This is why strain rate matters so much.',null,true,2,2,494) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f100','geological-assistant','geological-assistant-m2','Behaviour of minerals and rocks under deformation conditions','Tectonites are rocks whose fabric was made by deformation. S-tectonites have a dominant foliation, L-tectonites a dominant lineation, and L-S tectonites have both.','S = surface (planes), L = line. Flattening strain gives S-tectonites, constriction (stretching) gives L-tectonites, and plane strain gives L-S tectonites.',null,true,2,2,495) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f101','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','In tangential longitudinal strain (neutral-surface) folding, the outer arc of a competent layer is stretched, the inner arc is shortened, and a neutral surface between them has no strain.','Bend a thick rubber eraser: the outside of the bend stretches and the inside wrinkles. Tension cracks can open on the outer arc of such folds.',null,true,2,2,496) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f102','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','In buckle folds, wavelength increases with the thickness of the competent layer and with its viscosity contrast against the host rock (Biot–Ramberg theory).','Thick, stiff beds make large, widely spaced folds; thin beds make small, closely spaced folds. So thick and thin beds in one outcrop fold at different sizes.',null,true,2,2,497) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f103','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','Ptygmatic folds are tight, lobate, meandering folds of thin competent veins (quartz, pegmatite) in a much weaker host such as migmatite or gneiss.','They look like coiled intestines. They form by buckling when the vein is far stiffer than the rock around it.',null,true,2,2,498) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f104','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','Parasitic (minor) folds are S- or Z-shaped on the limbs and M-shaped at the hinge of a larger fold. Their axes are parallel to the larger fold''s axis (Pumpelly''s rule).','S and Z shapes occur on opposite limbs, so they show on which side the nearest antiform lies. Older books call them drag folds.',null,true,3,1,499) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f105','geological-assistant','geological-assistant-m2','Mechanism of folding and faulting','A listric fault is a curved normal fault, concave upward, that flattens with depth. Its hanging wall commonly bends into a rollover anticline.','Listric means shovel-shaped. Growth faults in deltas are listric faults that move during deposition, so beds are thicker on the downthrown side. Rollovers trap oil and gas.',null,true,2,2,500) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f106','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','A strike-slip fault is dextral (right-lateral) if the block across the fault appears to have moved to the right, and sinistral (left-lateral) if it moved to the left.','The answer is the same from either side of the fault. Wrench, tear and transcurrent faults are other names for strike-slip faults. The San Andreas Fault is dextral.',null,true,3,1,501) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f107','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Relative to the beds it cuts, a strike fault runs parallel to the strike of the beds, a dip fault parallel to their dip direction, and an oblique fault diagonally.','A strike fault is also called a longitudinal fault and a dip fault a transverse fault. This naming is about map direction only, not about normal or reverse movement.','TNPSC Geology paper (code 394, year not stated)',true,2,2,502) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f108','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Strike faults make beds repeat or go missing at the surface. Folds repeat beds in mirror-image order (A-B-C-B-A); faults repeat them in the same order (A-B-C-A-B-C).','A fold bends the same beds back, so the order reverses about the axis. A fault just shifts the pile, so the order starts again.','IIT-JAM Geology 2019',true,3,1,503) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f109','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','An imbricate (schuppen) zone is a stack of overlapping thrust slices that all dip the same way. A duplex is such a stack bounded by a floor thrust below and a roof thrust above.','Imbricate means overlapping like roof tiles. Thrusts climb in steps: flats along weak beds and ramps across strong beds.',null,true,2,2,504) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f110','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Pseudotachylite is a dark, glassy vein rock made by frictional melting during very fast (earthquake) slip on a fault.','It looks like tachylite (basalt glass) but is not volcanic, hence ''pseudo''. It is sometimes called a fossil earthquake.',null,true,2,2,505) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f111','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Extension (tension) joints open at right angles to σ3 and are parallel to σ1. Their faces often show plumose (feather-like) markings. Shear joints form as conjugate pairs.','A crack opens in the direction of least squeeze. Plumose marks fan out from where the crack started and prove the walls pulled apart instead of sliding.',null,true,3,1,506) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f112','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','In spaced (disjunctive) cleavage, thin cleavage domains are separated by slabs of less-deformed rock called microlithons. In continuous cleavage, such as slaty cleavage, the fabric runs through the whole rock.','Fracture cleavage and crenulation cleavage are spaced types. If you can see separate cleavage planes with rock between them, it is spaced.','TNPSC Geology paper (code 394, year not stated)',true,2,2,507) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f113','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Cleavage refraction: cleavage changes angle from bed to bed, lying at a high angle to bedding in competent beds (sandstone) and at a lower angle in incompetent beds (shale).','Weak beds take up more shear, which turns their cleavage closer to bedding. In a graded bed the cleavage curves smoothly, which also shows the way up.',null,true,2,2,508) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f114','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','S-C fabric in mylonites has S (foliation) planes oblique to C (shear) planes. The acute angle between S and C points in the direction of shear.','From French: schistosité and cisaillement (shear). Other shear-sense indicators are tailed porphyroclasts (σ and δ types) and mica fish. Stretching lineation gives the line of movement.',null,true,2,2,509) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f115','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Way-up (top-and-bottom) criteria include graded bedding (coarse at the base), cross-bedding (cut off at the top), mud cracks (wide at the top), sole marks (on the base) and convex tops of pillow lava.','In folded country beds may be upside down. These primary structures show which side was up when the rock formed, so overturned limbs can be found.',null,true,3,1,510) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f116','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Disharmonic folds change in shape or wavelength from layer to layer. Conjugate folds are a pair with axial planes dipping toward each other; a box fold is one example.','Disharmony comes from beds of different thickness and strength folding in their own way, often above a weak layer that takes up the misfit.','TNPSC Geology paper (code 394, year not stated)',true,2,2,511) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f117','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','A monocline is a step-like bend with one steep limb in otherwise flat or gently dipping beds. A homocline is a set of beds dipping evenly in one direction.','Mono = one limb. Monoclines often form in cover beds draped over a fault in the basement below.',null,true,2,2,512) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f118','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The Narmada–Son Lineament is an ENE–WSW zone of deep faults across central India. The Narmada flows west in its rift valley; the Tapi follows a parallel rift to the south (SONATA zone).','It lies between the Vindhyan country to the north and the Satpura–Gondwana country to the south. It is old but still active: the 1997 Jabalpur earthquake occurred on it.',null,true,3,1,513) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f119','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The Great Boundary Fault of Rajasthan trends NE–SW near Chittorgarh and brings the older rocks of the Aravalli belt against the Vindhyan Supergroup.','It marks the western edge of the Vindhyan basin in Rajasthan. Vindhyan beds near it are dragged and steeply tilted.',null,true,2,2,514) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f120','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The Palghat–Cauvery Shear Zone system (with the Moyar and Bhavani shear zones) crosses southern India roughly east–west and separates the Dharwar Craton–Nilgiri region from the Madurai Block.','It is the main crustal boundary inside the Southern Granulite Terrain. In Kerala its surface expression is the Palghat Gap, the widest break in the Western Ghats.',null,true,2,2,515) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f121','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The Indus–Tsangpo Suture Zone, with its ophiolites, marks where the Indian and Eurasian plates joined. The South Tibetan Detachment is a normal-sense fault at the top of the Higher Himalayan crystalline rocks.','Suture = stitch line between two plates; ophiolites are slices of old ocean floor caught in it. Order from north to south: suture, detachment, MCT, MBT, MFT.',null,true,3,1,516) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f122','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Himalayan examples: the Almora klippe (Kumaun) is a remnant of a crystalline thrust sheet; the Kishtwar and Kulu–Rampur windows expose Lesser Himalayan rocks below the Main Central Thrust sheet.','Klippe = island of the upper sheet; window = hole through the upper sheet. Both prove that the crystalline sheet once travelled far over the Lesser Himalaya.',null,true,2,2,517) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f123','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','Regional strike of Indian Precambrian belts: Dharwar NNW–SSE, Aravalli NE–SW, Eastern Ghats NE–SW and Satpura ENE–WSW.','These old trends guide later structures too. For example, the Narmada–Son zone follows the Satpura trend.',null,true,3,1,518) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f124','geological-assistant','geological-assistant-m2','Structural analysis of folds, cleavages, lineations, joints and faults','The Singhbhum Shear Zone (Copper Belt Thrust) of Jharkhand is an arcuate ductile shear zone about 200 km long. It hosts copper (Mosabani) and uranium (Jaduguda) deposits.','Sheared, crushed rock gave easy paths for ore fluids. It runs along the northern edge of the Singhbhum craton.',null,false,2,2,519) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f125','geological-assistant','geological-assistant-m2','Superposed deformation','In repeatedly deformed areas, S0 is bedding, S1 and S2 are successive foliations, F1 and F2 fold generations, L1 and L2 lineations, and D1 and D2 the deformation phases.','The number gives the order in time. Example: S1 is the axial-plane cleavage of F1 folds, both made during D1.',null,true,2,2,520) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f126','geological-assistant','geological-assistant-m2','Superposed deformation','Signs of superposed folding: folded axial planes and cleavages, refolded fold hinges, bent early lineations, crenulation of an early foliation, and dome, crescent or hook outcrop patterns.','An axial plane or cleavage starts flat or planar. If it is now folded, a second folding must have happened after it formed.',null,true,3,1,521) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f127','geological-assistant','geological-assistant-m2','Superposed deformation','In Ramsay Type 1 interference the axial planes of the first folds stay nearly planar. In Types 2 and 3 the first axial planes are themselves folded.','In Type 1 only the early hinge lines are bent up and down. In Type 3 the early hinges stay straight but the axial planes are bent. In Type 2 both are bent.',null,true,2,2,522) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f128','geological-assistant','geological-assistant-m2','Superposed deformation','A culmination is a high point and a depression a low point along a fold hinge whose plunge changes direction. A doubly plunging fold is called a pericline.','A doubly plunging anticline makes an elongate dome on the map, with beds dipping away on all sides. Such folds are non-cylindrical.',null,true,2,2,523) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f129','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','A pressure shadow (strain shadow) is a low-strain zone on two opposite sides of a rigid grain, filled with new quartz, calcite or chlorite and drawn out along the foliation.','The hard grain shields the rock beside it from the squeeze, and minerals grow in the sheltered gap. Pyrite and garnet often have them.',null,true,2,2,524) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f130','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','A porphyroclast is a large relict grain that survived grain-size reduction in a mylonite, such as a feldspar ''augen'' (eye). A porphyroblast is a newly grown metamorphic crystal.','-clast = broken remnant, -blast = new growth. Porphyroclasts are older than the shearing, and their tails show the shear sense.',null,true,3,1,525) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f131','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','If straight inclusion trails (Si) in a porphyroblast are cut off sharply and lie at an angle to the outside foliation (Se), the crystal grew between two deformation phases (inter-tectonic).','The crystal overgrew the first foliation after D1. Then D2 turned the crystal or built a new foliation around it, so inside and outside no longer match.',null,true,2,2,526) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f132','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','Bent micas, kinked crystals and undulose extinction show deformation outlasted crystallization. Strain-free polygonal grains meeting at 120° triple junctions show recrystallization outlasted deformation.','Heat heals strained crystals (annealing). A polygonal arc, a microfold outlined by straight, unbent mica flakes, likewise shows the micas recrystallized after folding.',null,true,3,1,527) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f133','geological-assistant','geological-assistant-m2','Time-relationship between crystallization and deformation','Randomly oriented contact-metamorphic porphyroblasts (andalusite, cordierite) that overprint a regional foliation show that the granite intrusion is post-tectonic.','If the granite had come before or during the deformation, its aureole minerals would be wrapped, broken or lined up by the foliation.',null,true,2,2,528) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f134','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','Overlap (onlap): during transgression each younger bed extends farther onto the old land surface than the bed below. Offlap: during regression each younger bed covers a smaller area.','Rising sea = beds spread landward (overlap). Falling sea = beds retreat seaward (offlap). Overstep is different: one bed rests on the cut edges of several older beds.',null,true,3,1,529) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f135','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','Field signs of an unconformity: a basal conglomerate with pebbles of the rocks below, an old weathered zone (palaeosol), a difference in dip, cut-off dykes or faults, and a jump in fossil age or metamorphic grade.','All of them show that the lower rocks were exposed and eroded before the upper rocks were laid down.',null,true,3,1,530) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f136','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','A mantled gneiss dome (Eskola) has a core of older granitic gneiss basement, remobilised and domed up, wrapped by a mantle of younger metamorphosed cover rocks.','During a later mountain-building event the old basement became hot and light and rose as a dome, lifting its cover like a cloak.',null,true,2,2,531) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f137','geological-assistant','geological-assistant-m2','Unconformities and basement-cover relations','In Rajasthan the Banded Gneissic Complex (BGC) is the Archaean basement on which the Proterozoic Aravalli Supergroup was deposited, with an erosional unconformity between them.','This is a classic Indian basement–cover pair, described by A. M. Heron. The Peninsular Gneiss plays a similar basement role for the Dharwar belts.',null,true,2,2,532) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f138','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Hans Cloos''s primary joints in granite plutons: cross (Q) joints at right angles to the flow lines, longitudinal (S) joints steep and parallel to the flow lines, and flat-lying (L) joints.','Q joints open by stretching along the flow and often carry aplite or pegmatite dykes. Quarrymen use the related rift, grain and hardway splitting directions.',null,true,2,2,533) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f139','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','In magmatic stoping, blocks of roof rock break off and sink into the magma, leaving xenoliths. A roof pendant is a remnant of roof rock hanging down into a batholith.','Stoping is passive emplacement: magma makes room by swallowing its roof. Forceful emplacement instead pushes the wall rocks aside and bends their foliation parallel to the contact.',null,true,2,2,534) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f140','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Dykes open at right angles to σ3, the least compressive stress, so a dyke swarm trends parallel to the σ1–σ2 plane. Radial dykes fan out from a volcanic centre.','Magma wedges rock apart in the easiest direction. A swarm of parallel dykes therefore records the direction of crustal stretching.',null,true,2,2,535) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f141','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Salt structures grow from salt pillows (cover not pierced) into salt domes or stocks (piercing plugs) and salt walls (long ridges). Salt withdrawal forms a rim syncline around a dome.','Salt flows sideways into the rising dome, so the ground around it sinks. Beds over the crest are arched and cut by radial normal faults and a central graben.',null,true,2,2,536) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2a-f142','geological-assistant','geological-assistant-m2','Structural behaviour of igneous rocks, diapirs and salt domes','Classic salt-dome provinces are the US Gulf Coast, the Zechstein basin of north Germany and the North Sea, and the Zagros–Persian Gulf region, where Hormuz salt reaches the surface as salt glaciers.','All have a thick, deeply buried salt layer under younger sediments. In the dry climate of Iran the salt is not dissolved, so it flows out over the ground.',null,true,2,2,537) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f001','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','Nicolaus Steno (1669) gave three basic laws of stratigraphy: superposition, original horizontality and lateral continuity.','Steno = S for Strata. Superposition means that in an undisturbed pile the lowest bed is the oldest.','Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024; Kerala University M.Sc. Geology model questions (GL 231)',true,3,1,538) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f002','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','William Smith stated the principle of faunal succession: fossil assemblages follow one another in a fixed, recognisable order. He made the first geological map of England and Wales (1815).','Smith was a canal surveyor who saw the same fossils in the same order everywhere. This lets us match beds by fossils.','Kerala University M.Sc. Geology model questions (GL 231)',true,3,1,539) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f003','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','Walther''s Law of facies: facies found one above another in a conformable vertical sequence were deposited side by side at the same time.','Environments shift sideways as the sea advances or retreats, so side-by-side belts end up stacked. It fails across an unconformity (a break in deposition).',null,true,3,1,540) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f004','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','James Hutton founded uniformitarianism (''the present is the key to the past'') and first recognised an angular unconformity, at Siccar Point, Scotland.','The same slow processes seen today shaped old rocks. The opposite idea, catastrophism, is linked to Cuvier.',null,true,3,1,541) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f005','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','Principle of cross-cutting relationships: a dyke, fault or erosion surface is younger than the rocks it cuts. Principle of inclusions: fragments are older than the rock that contains them.','You cannot cut a cake before it is baked. A pebble must exist before it is caught up in a conglomerate.','Kerala University M.Sc. Geology model questions (GL 231)',true,2,2,542) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f006','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','The term ''facies'' was introduced by Amanz Gressly in 1838 for the total rock and fossil character of a sedimentary unit.','Facies means ''face'' or appearance of a rock. Gressly worked in the Jura Mountains of Switzerland.',null,true,2,2,543) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f007','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','Lithostratigraphic units in descending rank are Supergroup, Group, Formation, Member and Bed.','These units are based only on rock type, not on age or fossils. Big to small: S-G-F-M-B.','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,3,1,544) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f008','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','The Formation is the fundamental unit of lithostratigraphy; it must be mappable at the surface or traceable in the subsurface.','Geological maps are built from formations. A formation name has a place name plus a rock name or the word Formation, e.g. Narji Limestone.','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,3,1,545) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f009','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','Chronostratigraphic (rock) units Eonothem, Erathem, System, Series and Stage match the geochronologic (time) units Eon, Era, Period, Epoch and Age.','Rock units are the rocks formed during the matching time unit. System pairs with Period, Series with Epoch, Stage with Age.',null,true,3,1,546) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f010','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','For chronostratigraphic (rock) units we use Lower, Middle and Upper; for geochronologic (time) units we use Early, Middle and Late.','Rocks have a position, so lower or upper. Time has no position, so early or late. Example: Upper Cretaceous rocks formed in Late Cretaceous time.',null,true,2,2,547) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f011','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','The biozone is the basic unit of biostratigraphy. Main kinds are range zone, interval zone, assemblage zone, abundance (acme) zone and lineage zone.','A biozone is a body of rock defined by its fossils. An assemblage zone uses a natural association of three or more taxa (kinds of fossils).','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,2,2,548) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f012','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','A stratotype (type section) is the designated reference section that defines a stratigraphic unit or boundary. The original one named by the author is the holostratotype.','It works like a standard metre bar for a rock unit. Later substitutes are called lectostratotype or neostratotype.','Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,2,2,549) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f013','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','A GSSP (Global Boundary Stratotype Section and Point), the ''golden spike'', fixes the base of a stage at one point in one rock section. It is ratified by the IUGS.','Only the base is defined; the top of a stage is the base of the next. The first GSSP was the Silurian-Devonian boundary at Klonk, Czech Republic (1972).','Kerala University M.Sc. Geology model questions (GL 231)',true,3,1,550) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f014','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','Most Precambrian boundaries are fixed by a GSSA (Global Standard Stratigraphic Age), a round number in years, not by a point in rock. Example: Archean-Proterozoic at 2500 Ma.','Old rocks lack good fossils for a spike, so an agreed age is used. The Ediacaran is an exception: it has a GSSP in South Australia.',null,true,2,2,551) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f015','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','The International Stratigraphic Guide (ed. Hedberg 1976; 2nd ed. Salvador 1994) of the International Commission on Stratigraphy is the world standard for stratigraphic classification and naming.','It keeps rock (litho), fossil (bio) and time-rock (chrono) units as separate, independent categories.',null,true,2,2,552) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f016','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','India follows the Code of Stratigraphic Nomenclature of India, published by the Geological Survey of India as Miscellaneous Publication No. 20 (1971).','After this code the old words ''System'' and ''Series'' for rock packages were replaced, e.g. Cuddapah System became Cuddapah Supergroup.',null,false,2,2,553) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f017','geological-assistant','geological-assistant-m2','Nomenclature and the modern stratigraphic code','Lithostratigraphic boundaries can be diachronous (cut across time), but chronostratigraphic boundaries are isochronous (same age everywhere).','A beach sand laid down by an advancing sea is older at one end than the other. So rock boundaries are not time lines.',null,true,2,2,554) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f018','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Radioactive decay follows N = N0 e^(-lambda t); half-life = 0.693 / lambda. After n half-lives the fraction of parent left is 1/2^n.','Lambda is the decay constant (chance of decay per year). Example: after 3 half-lives only 1/8 (12.5%) of the parent remains.',null,true,3,1,555) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f019','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Uranium-238 decays to lead-206 with a half-life of about 4.47 billion years, releasing 8 alpha and 6 beta particles.','The half-life is close to the age of the Earth, so about half of the original U-238 is still present.',null,true,3,1,556) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f020','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Uranium-235 decays to lead-207 (half-life about 704 million years) and thorium-232 decays to lead-208 (half-life about 14 billion years).','Odd goes to odd: 235 to 207. Lead-204 is the only lead isotope that is not made by decay.',null,true,3,1,557) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f021','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Zircon is the best mineral for U-Pb dating: it takes in uranium but rejects lead when it grows, and it survives weathering and metamorphism.','So nearly all lead in a zircon is from decay. Its closure temperature (below which lead cannot escape) is above 900 degrees C.',null,true,3,1,558) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f022','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','On a concordia diagram (Wetherill) 206Pb/238U is plotted against 207Pb/235U. Samples that lost lead fall on a discordia line; its upper intercept gives the crystallisation age.','Concordia is the curve where both uranium clocks agree. The lower intercept of the discordia line often marks the time of lead loss.',null,true,2,2,559) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f023','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Potassium-40 (half-life about 1.25 billion years) decays two ways: about 89% to calcium-40 by beta emission and about 11% to argon-40 by electron capture.','Only the argon branch is used for dating, because common calcium-40 is everywhere in rocks and hides the radiogenic part.',null,true,3,1,560) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f024','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','K-Ar dating suits micas, hornblende, sanidine, whole-rock basalt and glauconite. Loss of argon gas on reheating gives ages that are too young.','Argon is a gas and is not bound in the crystal, so heat lets it leak out. Glauconite lets us date sedimentary rocks directly.',null,true,3,1,561) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f025','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','In the 40Ar/39Ar method the sample is irradiated with fast neutrons in a reactor to turn potassium-39 into argon-39; step-heating then gives a plateau age.','Only argon isotope ratios are measured on one sample piece, so it is more precise than K-Ar. A flat plateau shows no argon loss.',null,true,2,2,562) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f026','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Rubidium-87 decays to strontium-87 by beta emission with a very long half-life of about 49 billion years. It suits micas, K-feldspar and whole-rock granites.','Rubidium follows potassium in minerals, so K-rich rocks are best. The long half-life makes it good for old rocks.',null,true,3,1,563) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f027','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','In an Rb-Sr isochron plot (87Sr/86Sr against 87Rb/86Sr) the slope gives the age and the intercept gives the initial 87Sr/86Sr ratio.','A low initial ratio (about 0.703) points to a mantle source. A high ratio (above about 0.710) points to melted old crust.',null,true,3,1,564) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f028','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Samarium-147 decays to neodymium-143 by alpha emission with a half-life of about 106 billion years. It is used for mafic and ultramafic rocks and garnet.','Sm and Nd are rare-earth elements that do not move easily during weathering or metamorphism, so the clock stays reliable in old altered rocks.','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,3,1,565) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f029','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Carbon-14 forms in the upper atmosphere when cosmic-ray neutrons hit nitrogen-14, and it decays back to nitrogen-14 by beta emission.','Living things keep taking in C-14. At death the intake stops and the clock starts.',null,true,3,1,566) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f030','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Carbon-14 has a half-life of 5,730 years and dates organic matter (wood, charcoal, shell, bone) and groundwater up to about 50,000 years. W. F. Libby developed it.','After about 9 half-lives too little C-14 is left to measure. Libby won the 1960 Nobel Prize in Chemistry for it.',null,true,3,1,567) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f031','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Fission-track dating counts damage trails made by spontaneous fission of uranium-238 in apatite, zircon, titanite, mica and volcanic glass.','Tracks heal (anneal) on heating; in apatite they fade above about 110 degrees C. So the method records cooling and uplift history.',null,true,3,1,568) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f032','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Closure (blocking) temperature is the temperature below which a mineral keeps its daughter isotope. It falls in the order zircon U-Pb > hornblende K-Ar > biotite K-Ar > apatite fission track.','A radiometric age is the time since the mineral cooled below this temperature. Different minerals from one rock therefore give a cooling path.',null,true,2,2,569) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f033','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Tritium (hydrogen-3) has a half-life of about 12.3 years and is used to identify and date young groundwater recharged in the last few decades.','Nuclear bomb tests in the 1950s-60s put a tritium spike in rain. Water with tritium is therefore modern recharge.',null,true,3,1,570) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f034','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Clair Patterson (1956) fixed the age of the Earth at about 4.55 billion years using lead isotopes in meteorites.','Earth''s first rocks are destroyed, so he dated meteorites that formed with the Earth. He used the Canyon Diablo iron meteorite as the starting lead.',null,true,2,2,571) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f035','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','The oldest known Earth mineral grains are detrital zircons from Jack Hills, Western Australia (about 4.4 Ga); the oldest known rock is the Acasta Gneiss, Canada (about 4.03 Ga).','Detrital means the zircons were eroded from a lost older rock. The Acasta age is used as the base of the Archean Eon.',null,true,2,2,572) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f036','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Luminescence dating (TL and OSL) measures the time since quartz or feldspar grains were last exposed to sunlight or heat. It is used for Quaternary sands, loess and pottery.','Buried grains store energy from natural radiation, and light resets them to zero. OSL = optically stimulated luminescence.',null,true,1,3,573) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f037','geological-assistant','geological-assistant-m2','Radioisotopes and measuring geological time','Rhenium-187 decays to osmium-187 (Re-Os method), which directly dates molybdenite, other sulphide ores and black shales.','Re and Os enter sulphide and organic-rich material, unlike most other clocks which need silicate minerals. So it dates ore deposits directly.',null,true,1,3,574) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f038','geological-assistant','geological-assistant-m2','Geological time-scale','The four eons from oldest to youngest are Hadean, Archean, Proterozoic and Phanerozoic. The first three together form the Precambrian, about 88% of Earth history.','Phanerozoic means ''visible life''. It began with the Cambrian Period.','Kerala University M.Sc. Geology model questions (GL 231)',true,3,1,575) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f039','geological-assistant','geological-assistant-m2','Geological time-scale','Hadean starts about 4600 Ma (ICS 4567), Archean about 4000 Ma (ICS 4031) and Proterozoic at 2500 Ma.','4567 is easy to recall (4-5-6-7). Exam keys mostly use the round 4600 and 4000 Ma; pick the ICS number only if it is the option offered.',null,true,3,1,576) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f040','geological-assistant','geological-assistant-m2','Geological time-scale','Proterozoic eras: Paleoproterozoic 2500-1600 Ma, Mesoproterozoic 1600-1000 Ma, Neoproterozoic 1000 to about 541 Ma (ICS now 538.8 Ma).','2500, 1600 and 1000 are round because they are agreed ages (GSSA). The top is the Cambrian base, fixed by a GSSP: 541 Ma in most books, 538.8 Ma on the current ICS chart.',null,true,3,1,577) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f041','geological-assistant','geological-assistant-m2','Geological time-scale','The Neoproterozoic has three periods: Tonian, Cryogenian (from about 720 Ma) and Ediacaran (from about 635 Ma).','Cryogenian = ''cold birth'', the time of Snowball Earth glaciations. Ediacaran has the first large soft-bodied animals.',null,true,2,2,578) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f042','geological-assistant','geological-assistant-m2','Geological time-scale','The base of the Cambrian (and Phanerozoic) is about 541 Ma in most textbooks (538.8 Ma on the current ICS chart). GSSP: Fortune Head, Newfoundland; marker trace fossil Treptichnus pedum.','Older books give 570 or 542 Ma; ICS revised 541 to 538.8 Ma in 2022. A trace fossil is a burrow or track, not a body.',null,true,3,1,579) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f043','geological-assistant','geological-assistant-m2','Geological time-scale','Palaeozoic periods in order are Cambrian, Ordovician, Silurian, Devonian, Carboniferous and Permian. Mesozoic periods are Triassic, Jurassic and Cretaceous.','Memory hook for the Palaeozoic: ''Camels Often Sit Down Carefully, Perhaps''.',null,true,3,1,580) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f044','geological-assistant','geological-assistant-m2','Geological time-scale','Base ages of Palaeozoic periods, textbook (ICS 2026 in brackets): Ordovician 485 (486.9), Silurian 444 (443.1), Devonian 419 (419.6), Carboniferous 359 (358.9), Permian 299 (298.9) Ma.','Rough hooks: 485, 444, 419, 359, 299. ICS shifted three of these slightly in Dec 2024. Exam options usually differ by tens of millions of years, so the round value is enough.',null,true,2,2,581) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f045','geological-assistant','geological-assistant-m2','Geological time-scale','Base ages of Mesozoic periods: Triassic 252 Ma (ICS 251.9), Jurassic 201 Ma (ICS 201.4) and Cretaceous 145 Ma (ICS now 143.1).','Most textbooks and answer keys use 145 Ma for the base of the Cretaceous; ICS revised it to 143.1 Ma in Dec 2024. Choose 145 unless only 143.1 is offered.',null,true,3,1,582) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f046','geological-assistant','geological-assistant-m2','Geological time-scale','The Cenozoic began 66 Ma (older books 65). Periods: Paleogene (Paleocene, Eocene, Oligocene), Neogene (Miocene, Pliocene; from about 23 Ma, ICS 23.04) and Quaternary (Pleistocene, Holocene; from 2.58 Ma).','Epoch hook: ''Put Eggs On My Plate Please, Honey''. The Quaternary base was lowered from 1.8 to 2.58 Ma in 2009.',null,true,3,1,583) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f047','geological-assistant','geological-assistant-m2','Geological time-scale','The Holocene began 11,700 years ago. Its youngest stage, the Meghalayan (from about 4,200 years ago), has its GSSP in a stalagmite from Mawmluh Cave, Meghalaya, India (ratified 2018).','It is the only stage named after an Indian state. The boundary marks a worldwide drought seen in the cave deposit.',null,true,3,1,584) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f048','geological-assistant','geological-assistant-m2','Geological time-scale','The ''Big Five'' mass extinctions are end-Ordovician, Late Devonian, end-Permian, end-Triassic and end-Cretaceous. The end-Permian (about 252 Ma) was the largest.','The end-Permian event killed about 90% of marine species, including the last trilobites. It is linked to the Siberian Traps eruptions.','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,3,1,585) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f049','geological-assistant','geological-assistant-m2','Geological time-scale','The end-Cretaceous extinction (66 Ma) removed non-avian dinosaurs and ammonites. It is marked worldwide by an iridium-rich clay layer and linked to the Chicxulub impact and Deccan volcanism.','Iridium is rare in the crust but common in meteorites. Alvarez and others (1980) found the layer at Gubbio, Italy.','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,3,1,586) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f050','geological-assistant','geological-assistant-m2','Geological time-scale','Cambrian was named by Sedgwick (1835), Silurian (1835) and Permian (1841) by Murchison, and Ordovician by Lapworth (1879).','Lapworth created the Ordovician to settle the Sedgwick-Murchison quarrel over overlapping rocks in Wales. Cambria = Latin for Wales; Silures and Ordovices were Welsh tribes; Permian from Perm in Russia.',null,true,2,2,587) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f051','geological-assistant','geological-assistant-m2','Geological time-scale','In March 2024 the IUGS and ICS rejected the proposal to make the Anthropocene a formal epoch, so the Holocene remains the current epoch.','The proposal wanted a start around 1952 with a marker at Crawford Lake, Canada. The word is still used informally.',null,true,2,2,588) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f052','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','Unfossiliferous rocks are correlated by lithological similarity, marker beds, position in sequence, unconformities, structural and metamorphic relations, radiometric ages, palaeomagnetism, geochemistry and well logs.','Without fossils we use physical and chemical ''fingerprints''. Radiometric dating is the most reliable of these for Precambrian rocks.',null,true,3,1,589) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f053','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','A good marker (key) bed is thin, distinctive, widespread and deposited quickly. Volcanic ash (tephra or bentonite) beds are the best examples.','An ash fall settles in days over a huge area, so it is a true time line. Toba ash (about 74,000 years old) is such a marker across peninsular India.',null,true,3,1,590) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f054','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','Magnetostratigraphy correlates rocks by their record of geomagnetic polarity reversals, which are worldwide and occur at the same time everywhere.','Iron minerals lock in the field direction when the rock forms. The pattern of normal and reversed zones works like a barcode.','Kerala University M.Sc. Geology model questions (GL 231); Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,3,1,591) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f055','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','The present Brunhes normal polarity chron began about 0.78 Ma. Before it came the Matuyama (reversed), Gauss (normal) and Gilbert (reversed) chrons.','Going back in time: B-M-G-G. The Gauss-Matuyama reversal at 2.58 Ma is used as the base of the Quaternary.',null,true,3,1,592) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f056','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','Chemostratigraphy correlates strata using chemical signals such as carbon-13, oxygen-18 and 87Sr/86Sr ratios, or element spikes like the iridium layer.','Seawater chemistry changes with time and is the same across the oceans, so rocks of the same age carry the same signal.','Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,2,2,593) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f057','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','In the marine oxygen-isotope record, odd-numbered stages are warm interglacials and even-numbered stages are cold glacials. Stage 1 is the Holocene.','Ice sheets lock up light oxygen-16, so seawater and shells become rich in oxygen-18 in cold times.',null,true,2,2,594) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f058','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','In sequence stratigraphy a depositional sequence is a package of related strata bounded above and below by unconformities or their correlative conformities.','A sequence records one cycle of sea-level fall and rise. Its parts are the lowstand, transgressive and highstand systems tracts.','Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,2,2,595) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f059','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','The maximum flooding surface marks the greatest landward advance of the sea; it separates the transgressive systems tract below from the highstand systems tract above.','It is often a thin, clay-rich, slowly deposited layer and gives a strong gamma-ray peak on well logs.',null,true,2,2,596) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f060','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','A varve is one year''s deposit in a glacial lake: a light, coarse summer layer plus a dark, fine winter layer. De Geer used varve counting for dating in Sweden.','Counting pairs is like counting tree rings. It gives absolute ages for late Quaternary deposits.',null,true,2,2,597) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f061','geological-assistant','geological-assistant-m2','Stratigraphic procedures of correlation of unfossiliferous rocks','In boreholes, unfossiliferous beds are correlated with geophysical well logs, mainly gamma-ray and resistivity (electric) logs.','Shale gives high gamma-ray counts and sandstone low, so each bed has a log shape that can be matched from well to well.',null,true,2,2,598) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f062','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','Peninsular India has five main Archean cratons: Dharwar, Bastar, Singhbhum, Bundelkhand and Aravalli. They are joined by mobile belts such as the Eastern Ghats and Satpura belts.','A craton is an old, stable block of crust. A mobile belt is a long zone of strong folding and metamorphism between cratons.','Kerala University M.Sc. Geology model questions (GL 231)',true,3,1,599) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f063','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Eparchaean Unconformity separates Archean basement from the overlying Proterozoic ''Purana'' basins. It is best seen at Tirumala (Tirupati), where Cuddapah quartzite rests on Archean granite.','It marks a very long gap of erosion. The Tirumala site is a National Geological Monument.',null,true,3,1,600) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f064','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Dharwar craton has a western block (older gneisses, wide schist belts rich in sediments) and an eastern block (younger granites, narrow gold-bearing volcanic belts such as Kolar and Hutti).','The two blocks meet along the Chitradurga shear zone; older books use the Closepet Granite as the divide.','Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,3,1,601) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f065','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Sargur Group (older than 3.0 Ga) is the oldest supracrustal unit of the Dharwar craton. It occurs as high-grade enclaves in the Peninsular Gneiss.','Supracrustal means rocks first laid down at the surface (lavas and sediments). Sargur ultramafic rocks host chromite at Nuggihalli, Karnataka.',null,true,3,1,602) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f066','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Peninsular Gneiss of Karnataka is a tonalite-trondhjemite-granodiorite (TTG) gneiss complex aged about 3.4-3.0 Ga. It is the basement to the Dharwar Supergroup.','TTG are sodium-rich granitic rocks typical of Archean crust. The name was given by W. F. Smeeth.',null,true,3,1,603) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f067','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Dharwar Supergroup (about 2.9-2.6 Ga) has a lower Bababudan Group and an upper Chitradurga Group.','B before C. It lies unconformably on the Peninsular Gneiss. R. Bruce Foote introduced the name Dharwar in 1886.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,3,1,604) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f068','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Bababudan Group starts with a uranium- and pyrite-bearing quartz-pebble conglomerate and has thick banded iron formation. The Chitradurga Group has polymict conglomerate, greywacke, carbonates and iron-manganese formations.','Bababudan and Kudremukh iron ores come from these banded iron formations. Polymict means pebbles of many rock types.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,2,2,605) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f069','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Closepet Granite is a north-south, potassium-rich granite belt about 400 km long in Karnataka, aged about 2.5 Ga (end of the Archean).','It is named after Closepet, now Ramanagara. Its intrusion marks the final stabilisation of the Dharwar craton.',null,true,3,1,606) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f070','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','Dharwar schist belts are India''s richest metal source: gold at Kolar and Hutti, iron and manganese at Sandur-Ballari, iron at Bababudan and Kudremukh, and chromite at Nuggihalli.','Schist (greenstone) belts are old volcanic-sedimentary belts. Hot fluids moving along their shear zones deposited the gold.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018; Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,3,1,607) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f071','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','Charnockite (orthopyroxene-bearing granite) was named by T. H. Holland after Job Charnock; its type area is St. Thomas Mount-Pallavaram, Chennai.','Job Charnock''s tombstone in Kolkata is made of this rock. Orthopyroxene (hypersthene) shows very hot, dry granulite-facies conditions.',null,true,3,1,608) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f072','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','Khondalite is a garnet-sillimanite-graphite gneiss named by T. L. Walker after the Khond tribe of Odisha. It is a metamorphosed clay-rich sediment.','Sillimanite and graphite show the parent was an aluminium- and carbon-rich mud. It is typical of the Eastern Ghats and south Kerala.',null,true,3,1,609) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f073','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Southern Granulite Terrain lies south of the Dharwar craton and is cut by the Moyar-Bhavani, Palghat-Cauvery and Achankovil shear zones. South of Palghat-Cauvery it is also called the Pandyan Mobile Belt.','Blocks north of Palghat-Cauvery had granulite metamorphism about 2.5 Ga. The Madurai and Trivandrum blocks to the south were reworked about 550 Ma (Pan-African).','UPSC Geologist Exam 2019 Geology Paper I (descriptive); Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,3,1,610) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f074','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Kerala Khondalite Belt (Trivandrum Block) lies south of the Achankovil shear zone. It has khondalite, garnet-biotite gneiss (leptynite) and charnockite, metamorphosed about 550 Ma.','It shows ''incipient charnockite'' patches formed in gneiss by CO2-rich fluids, classic at Ponmudi. The rocks supply sillimanite, monazite and zircon to Kerala beach sands.','Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,3,1,611) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f075','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','In Kerala the Wayanad Group (schists and ultramafics, Sargur equivalent) is the oldest unit; the Vengad Group of Kannur district (conglomerate, quartzite, mica schist) is equated with the Dharwar Supergroup.','Charnockite is the most widespread Precambrian rock of Kerala. Younger granites include Ambalavayal, Kalpetta and Munnar.','Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,2,2,612) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f076','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','In the Singhbhum craton the oldest units are the Older Metamorphic Group and Older Metamorphic Tonalite Gneiss (about 3.5-3.4 Ga), intruded by the Singhbhum Granite (about 3.3-3.1 Ga).','''Older Metamorphic'' is literally the oldest. The granite forms a large batholith (very big intrusion) in Jharkhand and Odisha.','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,3,1,613) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f077','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Iron Ore Group of Singhbhum-Odisha holds banded hematite jasper and India''s major hematite ores (Noamundi, Joda, Barbil, Kiriburu) in a horseshoe-shaped syncline. The Kolhan Group is the youngest cover.','Banded hematite jasper is a banded iron formation. Leaching of silica from it left rich hematite ore.','UPSC Geologist Exam 2019 Geology Paper I (descriptive)',true,3,1,614) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f078','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The arcuate Singhbhum Shear Zone (about 200 km long) hosts copper at Mosabani, Rakha and Surda and uranium at Jaduguda, India''s first uranium mine.','It is also called the Singhbhum copper belt thrust. Hot fluids moving along the sheared rocks deposited the metals.',null,true,3,1,615) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f079','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','In the Bastar craton and central India the Bailadila Group has rich iron ore, the Sausar Group has manganese ore with gondite, and Malanjkhand granitoid hosts India''s largest copper deposit.','Gondite is a spessartine garnet-quartz rock named by Fermor after the Gond tribe. The Dongargarh Supergroup of Bastar has Bijli rhyolite.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,3,1,616) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f080','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Bundelkhand craton is mainly Bundelkhand granite and gneiss (granite about 2.5 Ga), cut by giant quartz reefs trending NE-SW and mafic dyke swarms trending NW-SE.','The quartz reefs stand out as long ridges. The Vindhyan basin wraps around the craton; the Bijawar and Gwalior groups lie on its edges.',null,true,2,2,617) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f081','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','In Rajasthan the order from oldest to youngest is Banded Gneissic Complex (basement), Aravalli Supergroup, Delhi Supergroup (Alwar and Ajabgarh groups), Erinpura Granite and Malani Igneous Suite.','A. M. Heron set up this sequence. The Banded Gneissic Complex is Archean (about 3.3-2.5 Ga).','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,3,1,618) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f082','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Aravalli Supergroup hosts Zawar lead-zinc and Jhamarkotra stromatolitic rock phosphate; the Delhi Supergroup hosts Khetri copper; the older Bhilwara rocks host Rampura-Agucha lead-zinc.','Stromatolites are layered mounds built by microbes. Jhamarkotra near Udaipur is India''s largest rock phosphate mine.',null,true,3,1,619) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f083','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Erinpura Granite (about 850 Ma) marks the close of the Delhi orogeny. The Malani Igneous Suite (about 750 Ma) of western Rajasthan is mainly rhyolite and granite.','Malani is the largest felsic (silica-rich) volcanic province of India. It is overlain by the Marwar Supergroup.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,2,2,620) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f084','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Eastern Ghats Mobile Belt of Odisha and Andhra Pradesh is a granulite belt of khondalite, charnockite, anorthosite and alkaline rocks, metamorphosed mainly about 1000 Ma.','Its khondalite weathers to the East Coast bauxite (Panchpatmali). It also has manganese ore (kodurite) and graphite.',null,true,3,1,621) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f085','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Cuddapah Supergroup of Andhra Pradesh fills a crescent-shaped basin. Its groups, upward, are Papaghni, Chitravati and Nallamalai; the Kurnool Group lies unconformably above.','Hook: P-C-N then K. The Papaghni Group starts with Gulcheru Quartzite followed by Vempalle dolomite. W. King named it in 1872.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,3,1,622) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f086','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','Cuddapah basin minerals: baryte at Mangampeta (among the world''s largest deposits), uranium at Tummalapalle in Vempalle dolomite, and chrysotile asbestos at Pulivendla.','The asbestos formed where dolerite sills baked the Vempalle dolomite. Mangampeta baryte lies in Cumbum (Pullampet) shales of the Nallamalai Group.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,3,1,623) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f087','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Kurnool Group, upward, has Banganapalle Quartzite, Narji Limestone, Owk Shale, Paniam Quartzite, Koilkuntla Limestone and Nandyal Shale. Banganapalle conglomerates carry diamonds.','It is Neoproterozoic and much thinner than the Cuddapah. Narji Limestone is used for cement and as flooring slabs.',null,true,2,2,624) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f088','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Vindhyan Supergroup has a Lower Vindhyan Semri Group and, above an unconformity, the Upper Vindhyan Kaimur, Rewa and Bhander groups (in upward order).','Hook: S-K-R-B. It is more than 4 km thick and mostly unmetamorphosed and little deformed. T. Oldham named it in 1856.','UPSC Geologist Exam 2019 Geology Paper I (descriptive); Calicut Univ M.Sc. Applied Geology ''Stratigraphy and Indian Geology'' Nov 2024',true,3,1,625) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f089','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','Vindhyan economic products: diamonds at Panna (Majhgawan pipe and Rewa Group conglomerates), cement-grade limestone (Rohtas, Bhander) and red building sandstone.','The Majhgawan pipe cuts Kaimur sandstone and is about 1.07 Ga old. Vindhyan sandstone built the Red Fort and Sanchi Stupa.','Calicut Univ B.Sc. Geology ''Indian Geology'' Nov 2018',true,3,1,626) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f090','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','The Chhattisgarh Supergroup on the Bastar craton has a lower sandy Chandarpur Group and an upper limestone-shale Raipur Group, a major cement-limestone source.','It is a ''Purana'' basin like the Cuddapah and Vindhyan: flat-lying Proterozoic sediments on Archean basement.',null,true,2,2,627) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2b-f091','geological-assistant','geological-assistant-m2','Precambrian stratigraphy of India','In north Karnataka the Kaladgi Supergroup has a lower Bagalkot Group and an upper Badami Group. The Bhima Group of Kalaburagi is mostly limestone (Shahabad Limestone).','Badami cave temples are cut in flat Badami sandstone. Shahabad stone is used for cement and flooring; uranium occurs at Gogi in the Bhima basin.',null,true,2,2,628) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f001','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','A good index (zone) fossil has a short time range, a wide geographic spread, is abundant and is easy to identify.','A short life pins down the age; a wide spread lets far-apart rocks be matched. Ammonites, graptolites and planktonic foraminifera are classic examples.','IIT-JAM Geology 2022',true,3,1,629) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f002','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Body fossils are actual remains of an organism or their moulds and casts; trace fossils (ichnofossils) record activity - tracks, trails, burrows, borings and coprolites (fossil dung). The study of traces is ichnology.','A trace shows behaviour, not the body. Traces are almost always found where they were made, so they are good guides to the old environment.','IIT-JAM Geology 2023; IIT-JAM Geology 2024',true,3,1,630) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f003','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Fossilisation is favoured by hard parts (shell, bone, wood) and by quick burial in fine sediment with little oxygen.','Burial shuts out scavengers and decay. That is why shelled sea-floor animals dominate the fossil record and soft-bodied land animals are rare.',null,true,2,2,631) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f004','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','In permineralisation (petrifaction), minerals such as silica or calcite fill the pores of wood or bone; in replacement they substitute the original material, as in pyritised shells.','Permineralised wood keeps its cell structure, so it looks like wood but is stone. Pyrite replacement is common in black, oxygen-poor muds.',null,true,2,2,632) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f005','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','Carbonisation (distillation) drives off the volatile parts of an organism and leaves a thin carbon film; it is the usual preservation of leaves and graptolites.','Heat and pressure squeeze out water and gases, so only carbon stays - like a pressed black print of the leaf.',null,true,2,2,633) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
insert into geological_assistant.cards (id,course_id,module_id,subtopic,statement,reasoning,source_ref,verified,frequency,tier,order_index) values ('geological-assistant-u2c-f006','geological-assistant','geological-assistant-m2','Fossil record and geological time-scale','A mould is the impression left by a shell in the sediment; a cast forms when that hollow is later filled, copying the shape of the shell.','Mould = the negative (like a jelly mould). Cast = the positive copy made inside it. An internal mould of a shell is called a steinkern.','IIT-JAM Geology 2024',true,3,1,634) on conflict (id) do update set statement=excluded.statement,reasoning=excluded.reasoning,source_ref=excluded.source_ref,verified=excluded.verified,frequency=excluded.frequency,tier=excluded.tier;
